            $directorio_entidad = empty($entidad_text) ? $directorio_raiz : $directorio_raiz.$entidad_text."/";
            $directorio_com = $dir_adj_object."/".$periodo_com."/";
            $directorio_final = $directorio_entidad.$directorio_com;
