            if(!empty($dependencia_id)){
                $area_encargo = DependenciaPeer::retrieveByPK($dependencia_id);
                $firma_area[] = $area_encargo != null ? $area_encargo->getNombre() : $enviada_usuario_firmaOne->getUsuario()->getDependencia()->getNombre();
