    public function getDataEmptyRowFirmas($emptyRows = 2)
    {
        $fila_html = '';
        for($i = 0; $i < $emptyRows; $i++){
            $fila_html .= '<tr><td>&nbsp;</td></tr>';
        }
        return $fila_html;
    }

    public function getDataAreasOrCargosFirmas($data_str, $add_td = true)
    {
        if(!count($data_str)){ return ''; }
        $fila_html = '';
        foreach($data_str as $row_str){
            if($add_td){
                $fila_html .= '<td style="{%class%}">'.$row_str.'</td>';
            }else{
                $fila_html .= $row_str;
            }
        }
        return '<tr>'.$fila_html.'</tr>';
    }

    public function generateImgCodeCom($params = array())
    {
        try {
            $read_sections = array('keyprivate_watermark', 'url_virtual', 'acto_administrativo_sticker');
            $ini_array = simad_util::readConfigFileApp($read_sections);
            $genQR = isset($ini_array['acto_administrativo_sticker']) ? $ini_array['acto_administrativo_sticker'] : 'CODEBAR';

            if($genQR == 'QR')
            {
                $keyprivate = isset($ini_array['keyprivate_watermark']) ? $ini_array['keyprivate_watermark'] : null;
                $urlvirtual = isset($ini_array['url_virtual']) ? $ini_array['url_virtual'] : null;

                $hash_interno = ActoAdministrativoPeer::getHashComData($this);
                $encrypted_string = simad_util::encrypt_decrypt('encrypt', $hash_interno, $keyprivate);
                
                $text_radicado = sprintf('%s/%s=%s', sfConfig::get('publicUrl'), $urlvirtual, $encrypted_string);
                $tamano = isset($params['tamano']) ? $params['tamano'] : 10;
                $level = isset($params['level']) ? $params['level'] : 'H' ;
                $framesize = isset($params['framesize']) ? $params['framesize'] : 3;

                return simad_util::generateCodeQrInFile($text_radicado, $tamano, $level, $framesize);
            }
            else
            {
                $text_radicado = $this->getRadicadoCompuesto();
                $clearlabels = isset($params['clearlabels']) ? $params['clearlabels'] : false;
                $scale = isset($params['scale']) ? $params['scale'] : 1;
                $height = isset($params['height']) ? $params['height'] : 25;
                $fsize = isset($params['fsize']) ? $params['fsize'] : 8;
                $dpi = isset($params['dpi']) ? $params['dpi'] : 72;

                return simad_util::generateCodeBarInFile($text_radicado, $clearlabels, $scale, $height, $fsize, $dpi);
            }
        } catch (PropelException $ex) {
            return null;
        } catch(\Exception $ex) {
            return null;
        }catch (\Throwable $ex) {
            return null;
        }
    }

    public function generateCodeBarInFile($clearlabels = false, $scale = 1, $height = 25, $fsize = 8, $dpi = 72)
    {
        try {
            $text_radicado = $this->getRadicadoCompuesto();
            return simad_util::generateCodeBarInFile($text_radicado, $clearlabels, $scale, $height, $fsize, $dpi);
        } catch(\Exception $e) {
            return null;
        }
    }

    public function sendMailAprob(Usuario $usuario, $encabezado_cuerpo = "")
    {
        if (trim($encabezado_cuerpo) == "") {
            if (in_array($this->getEstadoactoadministrativoId(), array(1, 2, 3, 4))) {
                $encabezado_cuerpo = "Este es un mensaje para informarle que hay un Acto Administrativo pendiente para su aprobacion <br>";
                $encabezado_cuerpo .= "Podra consultar el Acto Administrativo en su buzon de borradores con la siguiente informacion:";
            } else {
                $encabezado_cuerpo = "Este es un mensaje para informarle que se le radico un Acto Administrativo para su revision <br>";
                $encabezado_cuerpo .= "Podra consultar el Acto Administrativo en su buzon de radicados con la siguiente informacion:";
            }
        }
        //***************************************************************************
        $cuerpo = '
        <html>
        <head>
        <title></title>
        </head>
        <body>
        <div id="cotenedor">
        <br>' . $encabezado_cuerpo . '     
        <br>
        <br>
        <b>Fecha Documento:</b> ' . $this->getFechaCreacion() . ' <br>    
        <b>Asunto:</b> ' . ($this->getAsunto()) . '<br>
        <b>Dependencia:</b> ' . ($this->getDependencia()) . '<br>
        <b>Fecha Documento:</b> ' . ($this->getFechaCreacion()) . '<br>';
        //***************************************************************************
        if (in_array($this->getEstadoactoadministrativoId(), array(1, 2, 3, 4))) {
            $cuerpo .= '<br><b>Estado:</b> Pendiente para aprobacion <br>';
        } else {
            $cuerpo .= '<br><b>Radicado:</b> ' . $this->getRadicadoCompuesto() . '<br>';
        }
        //***************************************************************************
        $cuerpo .= '<br></div></body></html>';
        //*****************************************************************************
        $cabeceras = "Content-type: text/html\r\n";
        $baseMail = new BaseMailSimad();
        //*****************************************************************************
        if (in_array($this->getEstadoactoadministrativoId(), array(1, 2, 3, 4))) {
            $baseMail->SetSubject('SGDEA : Aprobacion Acto Administrativo #consecutivo ' . $this->getPrimaryKey());
        } else {
            $baseMail->SetSubject('SGDEA : Acto Administrativo #Radicado ' . $this->getRadicadoCompuesto());
        }
        //*****************************************************************************
        $baseMail->SetMsgHTML($cuerpo);
        $baseMail->SetAddAddress($usuario->getEmail(), $usuario->getEmail());
        $response_email = $baseMail->InitSend();
        if ($response_email === true) {
            $baseMail->writetolog("Alerta enviada: " . $this->getPrimaryKey() . " Enviado a: " . $usuario->getEmail());
            return true;
        } else {
            $messages_error = "Error al enviar alerta: " . $this->getPrimaryKey() . " Cuenta correo: " . $usuario->getEmail();
            $baseMail->writetolog($messages_error);
            return $response_email === false ? false : (empty($response_email) ? $messages_error : $response_email);
        }
    }

    const MAIL_ACCION_SOLICITUD_ETAPA = 'SOLICITUD_ETAPA';
    const MAIL_ACCION_FIRMA = 'FIRMA';
    const MAIL_ACCION_DEVOLUCION = 'DEVOLUCION';
    const MAIL_ACCION_CAMBIO_VERSION = 'CAMBIO_VERSION';
    const MAIL_ACCION_RADICACION = 'RADICACION';
    const MAIL_ACCION_FINALIZACION = 'FINALIZACION';

    /**
     * Texto (asunto corto + introducción) de la alerta de correo según el tipo de evento del flujo.
     * UARIV-202605 CA-2.2: cubre solicitud de etapa (revisión/firma), firma realizada, devolución,
     * cambio de versión, radicación y finalización.
     */
    private function getInfoMailFlujoEtapa($accion, $etapa_nombre = null)
    {
        switch ($accion) {
            case self::MAIL_ACCION_SOLICITUD_ETAPA:
                return array(
                    'asunto' => 'Etapa pendiente' . ($etapa_nombre ? ' - ' . $etapa_nombre : ''),
                    'intro'  => 'Este es un mensaje para informarle que tiene una etapa pendiente' . ($etapa_nombre ? ' (' . $etapa_nombre . ')' : '') . ' en el siguiente Acto Administrativo.',
                );
            case self::MAIL_ACCION_FIRMA:
                return array(
                    'asunto' => 'Firma realizada',
                    'intro'  => 'Este es un mensaje para informarle que se realizó una firma en el siguiente Acto Administrativo.',
                );
            case self::MAIL_ACCION_DEVOLUCION:
                return array(
                    'asunto' => 'Acto Administrativo devuelto',
                    'intro'  => 'Este es un mensaje para informarle que el siguiente Acto Administrativo fue devuelto a su etapa' . ($etapa_nombre ? ' (' . $etapa_nombre . ')' : '') . '.',
                );
            case self::MAIL_ACCION_CAMBIO_VERSION:
                return array(
                    'asunto' => 'Cambio de versión',
                    'intro'  => 'Este es un mensaje para informarle que el contenido del siguiente Acto Administrativo fue modificado luego de su revisión o aprobación.',
                );
            case self::MAIL_ACCION_RADICACION:
                return array(
                    'asunto' => 'Acto Administrativo radicado',
                    'intro'  => 'Este es un mensaje para informarle que el siguiente Acto Administrativo fue radicado.',
                );
            case self::MAIL_ACCION_FINALIZACION:
                return array(
                    'asunto' => 'Proceso de aprobación finalizado',
                    'intro'  => 'Este es un mensaje para informarle que finalizó el proceso de aprobación del siguiente Acto Administrativo.',
                );
            default:
                return array('asunto' => 'Notificación', 'intro' => 'Este es un mensaje relacionado con el siguiente Acto Administrativo.');
        }
    }

    /**
     * Alerta por correo de un evento del flujo de aprobación (UARIV-202605, CA-2.1/CA-2.2).
     * El cuerpo incluye, como mínimo (CA-2.1.3): ID de la comunicación, estado actual, acción
     * realizada, fecha/hora y usuario responsable. Usa el mismo mecanismo de envío (BaseMailSimad)
     * que el resto de la aplicación.
     */
    public function sendMailFlujoEtapa(Usuario $usuario_destino, $accion, Usuario $usuario_responsable = null, $observacion = null, $etapa_nombre = null)
    {
        if (empty(trim($usuario_destino->getEmail()))) {
            return false;
        }
        //***************************************************************************
        $info = $this->getInfoMailFlujoEtapa($accion, $etapa_nombre);
        $estado_actual = $this->getEstadoActoAdministrativo() ? $this->getEstadoActoAdministrativo()->getDescripcion() : '';
        //***************************************************************************
        $cuerpo = '
        <html>
        <head>
        <title></title>
        </head>
        <body>
        <div id="cotenedor">
        <br>' . $info['intro'] . '
        <br>
        <br>
        <b>ID Comunicación:</b> ' . $this->getPrimaryKey() . '<br>
        <b>Asunto:</b> ' . ($this->getAsunto()) . '<br>
        <b>Dependencia:</b> ' . ($this->getDependencia()) . '<br>
        <b>Estado actual:</b> ' . $estado_actual . '<br>
        <b>Acción realizada:</b> ' . $info['asunto'] . '<br>
        <b>Fecha y hora:</b> ' . date('Y-m-d H:i:s') . '<br>
        <b>Usuario responsable:</b> ' . ($usuario_responsable ? $usuario_responsable->getNombreAll() : '') . '<br>';
        if (trim($this->getNumeroResolucion())) {
            $cuerpo .= '<b>Radicado:</b> ' . $this->getRadicadoCompuesto() . '<br>';
        }
        if (!empty($observacion)) {
            $cuerpo .= '<br><b>Observación:</b> ' . htmlspecialchars(trim($observacion)) . '<br>';
        }
        $cuerpo .= '<br></div></body></html>';
        //***************************************************************************
        $baseMail = new BaseMailSimad();
        $baseMail->SetSubject('SGDEA : ' . $info['asunto'] . ' - Acto Administrativo #' . $this->getPrimaryKey());
        $baseMail->SetMsgHTML($cuerpo);
        $baseMail->SetAddAddress($usuario_destino->getEmail(), $usuario_destino->getEmail());
        $response_email = $baseMail->InitSend();
        if ($response_email === true) {
            $baseMail->writetolog("Alerta flujo (" . $accion . ") enviada: " . $this->getPrimaryKey() . " Enviado a: " . $usuario_destino->getEmail());
            return true;
        }
        //***************************************************************************
        $messages_error = "Error al enviar alerta flujo (" . $accion . "): " . $this->getPrimaryKey() . " Cuenta correo: " . $usuario_destino->getEmail();
        $baseMail->writetolog($messages_error);
        return false;
    }

    /**
     * Envía sendMailFlujoEtapa() a varios destinatarios (p.ej. "todos los participantes" en
     * Firma realizada o Finalización), sin duplicar envíos al mismo usuario.
     */
    public function sendMailFlujoEtapaMasivo($accion, $usuarios_destino = array(), Usuario $usuario_responsable = null, $observacion = null, $etapa_nombre = null)
    {
        $ids_enviados = array();
        foreach ($usuarios_destino as $usuario_destino) {
            if ($usuario_destino instanceof Usuario && !in_array($usuario_destino->getPrimaryKey(), $ids_enviados)) {
                $this->sendMailFlujoEtapa($usuario_destino, $accion, $usuario_responsable, $observacion, $etapa_nombre);
                $ids_enviados[] = $usuario_destino->getPrimaryKey();
            }
        }
    }

    /**
     * Usuarios únicos que han participado en el flujo de este acto administrativo
     * (todas las filas de ACTOADMINISTRATIVO_USUARIO), opcionalmente excluyendo uno.
     */
    public function getParticipantesUnicos($excluir_usuario_id = null)
    {
        $usuarios = array();
        $ids_agregados = array();
        foreach ($this->getActoadministrativoUsuarios() as $uobject) {
            $usuario = $uobject->getUsuario();
            if ($usuario != null && !in_array($usuario->getPrimaryKey(), $ids_agregados) && $usuario->getPrimaryKey() != $excluir_usuario_id) {
                $usuarios[] = $usuario;
                $ids_agregados[] = $usuario->getPrimaryKey();
            }
        }
        return $usuarios;
    }

	/**
    * objectActions::getComIsArchivedExpediente()
    * valida si la comunicacion esta archivada
    * @return void
    */ 
    public function getComIsArchivedExpediente()
    {
        try
        {
            if(!empty($this->getMarcaVinculacion()))
            {
                $expediente_info = array();
                //********************************************************************************************
                $contenidodoc_id = $this->getContenidodocId();
                $contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($contenidodoc_id);
                //********************************************************************************************
                if($contenido_unidad_documental == null){
                    //no se encontro el contenido documental
                    return array('existe_expediente' => false,'titulo_expediente' => null);
                }
                //********************************************************************************************
                $unidaddocumental_id = $contenido_unidad_documental->getUnidaddocumentalId();
                $unidad_documental = $contenido_unidad_documental->getUnidadDocumental();
                if($unidad_documental == null){
                    //no se encontro el tipo documental
                    return array('existe_expediente' => false,'titulo_expediente' => null);
                }
                //********************************************************************************************
                $subserie = $unidad_documental->getSubserie();
                if($subserie == null){
                    //no se encontro la subserie
                    return array('existe_expediente' => false,'titulo_expediente' => null);
                }
                //********************************************************************************************
                $expediente_info['existe_expediente'] = true;
                $expediente_info['titulo_expediente'] = $unidad_documental->getCodigoTitulo();
                $expediente_info['subserie_expediente'] = $subserie->getDescripcion();
                $expediente_info['fase_archivo'] = $unidad_documental->getLocalizacionunidaddocumentalId();
                $expediente_info['unidaddocumental_id'] = $unidaddocumental_id;
                //********************************************************************************************                
                return $expediente_info;
            }
        }catch (PropelException $th) {
            return array('existe_expediente' => false,'titulo_expediente' => null);
        }catch (\Exception $th) {
            return array('existe_expediente' => false,'titulo_expediente' => null);
        }catch (\Throwable $th) {
            return array('existe_expediente' => false,'titulo_expediente' => null);
        }
    }

    /**
     * ActoAdministrativo::addServicioByCom()
    * crea una nueva solicitud de servicio con la informacion de la comunicacion 
    * @return mixed array('isError' => true|false, 'message' => '', 'object' => objeto con los datos del servicio)
    */ 
    public function addServicioByCom($usuario_servicio, $tiposervicio_id, $intersados_list = array(), $directorioexterno_id = null)
    {
        try {
            $estadoservicio_id = 1;
            $prioridadsolicitudservicio_id = 1;
            $detalle = 'Solicitud servicio de Acto Administrativo con radicado '.$this->getRadicadoCompuesto();
            $modulo_id = ModulesEnable::ActosAdministrativos;
            //****************************************************************************************
			if(empty($tiposervicio_id) || $tiposervicio_id == 0){
				return array('isError' => true, 'message' => 'El tipo de servicio no se encontro en el SGDEA', 'object' => null);
			}
			//****************************************************************************************
            $servicio_com = array();
            $servicio_com['usuario_id'] = $usuario_servicio;
            $servicio_com['regional_id'] = $this->getRegionalId();
            $servicio_com['directorioexterno_id'] = $directorioexterno_id;
            $servicio_com['tiposervicio_id'] = $tiposervicio_id;
            $servicio_com['estadoservicio_id'] = $estadoservicio_id;
            $servicio_com['prioridadsolicitudservicio_id'] = $prioridadsolicitudservicio_id;
            $servicio_com['detalle'] = $detalle;
            $servicio_com['folios'] = $this->getFolios();
            $servicio_com['coll_interesados'] = $intersados_list;
            //****************************************************************************************
            return ServicioPeer::createServicioByCom($servicio_com,$this->getPrimaryKey(),$modulo_id);
        }catch (PropelException $th) {
            return array('isError' => true, 'message' => $th->getMessage(), 'object' => null);
        }catch (\Exception $th) {
            return array('isError' => true, 'message' => $th->getMessage(), 'object' => null);
        }catch (\Throwable $th) {
            return array('isError' => true, 'message' => $th->getMessage(), 'object' => null);
        }
    }

    /**
     * ActoAdministrativo::getAttachmentCom()
    * Obtiene los anexos del registro
    * @return mixed array(ruta_archivos)
    */
    public function getAttachmentCom()
	{
		try {
			$attach_url = array();
            $pathtmp = simad_util::createPath(sfConfig::get('sf_web_dir'). DIRECTORY_SEPARATOR .'tmp'. DIRECTORY_SEPARATOR);
            $rootUrl = sfConfig::get('localUrl');
            //****************************************************************************************
			if(in_array($this->getEstadoactoadministrativoId(),array(6,9,8))){
				$files_adjuntos = preg_split("/[,]+/",$this->getRuta(), -1, PREG_SPLIT_NO_EMPTY);
				//************************************************************************************
				for($j = 0; $j < count($files_adjuntos); $j++){
                    if(trim($files_adjuntos[$j])){
                        try {
                            $filename = basename($files_adjuntos[$j]);
                            echo $fileurl = $rootUrl.$files_adjuntos[$j];

                            if(@file_exists($pathtmp.$filename)){
                                @unlink($pathtmp.$filename);
							}

                            $ch = curl_init($fileurl);
                            $fp = fopen($pathtmp.$filename, 'wb');
                            curl_setopt($ch, CURLOPT_FILE, $fp);
                            curl_setopt($ch, CURLOPT_HEADER, 0);
                            curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0);
                            curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 0);
                            curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36');
                            curl_exec($ch);

                            $tamanoDescargado = curl_getinfo($ch, CURLINFO_SIZE_DOWNLOAD);

                            curl_close($ch);
                            fclose($fp);

                            // Verificar integridad del archivo
                            if (!simad_util::verificarIntegridadArchivo($pathtmp.$filename, $tamanoDescargado)) {
                                @unlink($pathtmp.$filename);
                                continue;
                            }

                            if(file_exists($pathtmp.$filename)){
                                $attach_url[] = $pathtmp.$filename;
                            }
                        } catch (\Exception $th) {
                            //throw $th;
                        }
                    }
                }
			}
        } catch (PropelException $th) {
			$attach_url = null;
		} catch (\Exception $th) {
			$attach_url = null;
		}
		//*********************************************************************************************
		return $attach_url;
	}

